docs/validation/ce-skill-optimization-2026-10-29/remaining-27-acceptance/wave1/fixtures/explain/README.md # MiniLedger

A tiny personal expense-tracking demo app (Node.js, CommonJS).

- `src/server.js` — HTTP server with two endpoints: `POST /entries` (add an expense) and `GET /entries` (list them).
- Data is kept in memory; entries are `{id, amount, note, ts}`.

Known rough edges: adding an entry requires five fields typed by hand; no categories; no summary view.

docs/validation/ce-skill-optimization-2026-10-29/remaining-27-acceptance/wave1/fixtures/explain/package.json {
  "name": "mini-ledger",
  "version": "0.1.0",
  "private": true,
  "main": "src/server.js"
}

docs/validation/ce-skill-optimization-2026-10-29/remaining-27-acceptance/wave1/fixtures/explain/src/server.js const http = require('http');

const entries = [];

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/entries') {
    let body = '';
    req.on('data', (c) => { body += c; });
    req.on('end', () => {
      const { amount, note } = JSON.parse(body || '{}');
      entries.push({ id: entries.length + 1, amount, note, ts: Date.now() });
      res.end('ok');
    });
    return;
  }
  if (req.method === 'GET' && req.url === '/entries') {
    res.setHeader('content-type', 'application/json');
    res.end(JSON.stringify(entries));
    return;
  }
  res.statusCode = 404;
  res.end('not found');
});

server.listen(3000);


